arguments.command:
cd /work/submit && python3 - <<'PYEOF'
src = open('planb64.cpp').read()

# --- Fix 1: line length must be validated for every line, including ones
# that arrive complete inside a chunk.
old = '''            const std::size_t nl = buf_.find('\\n', pos_);
            if (nl != std::string::npos) {
                line.assign(buf_, pos_, nl - pos_);
                pos_ = nl + 1;
                return true;
            }
            if (at_eof_) {
                done_ = true;
                if (pos_ < buf_.size()) {
                    line.assign(buf_, pos_, buf_.size() - pos_);
                    pos_ = buf_.size();
                    return true;
                }
                return false;
            }'''
new = '''            const std::size_t nl = buf_.find('\\n', pos_);
            if (nl != std::string::npos) {
                if (nl - pos_ > kMaxLineBytes) fail("input line too long");
                line.assign(buf_, pos_, nl - pos_);
                pos_ = nl + 1;
                return true;
            }
            if (at_eof_) {
                done_ = true;
                if (pos_ < buf_.size()) {
                    if (buf_.size() - pos_ > kMaxLineBytes) fail("input line too long");
                    line.assign(buf_, pos_, buf_.size() - pos_);
                    pos_ = buf_.size();
                    return true;
                }
                return false;
            }'''
assert old in src
src = src.replace(old, new)

# --- Fix 2: never dereference argv[1] before checking argc.
old = '''        if (argc == 4 && std::strcmp(argv[1], "build") == 0) {'''
new = '''        if (argc < 2) fail("usage: planb64 build FIB IMAGE | planb64 lookup IMAGE"
                           " TRACE scalar | planb64 lookup IMAGE TRACE batch"
                           " BATCH_SIZE");
        if (argc == 4 && std::strcmp(argv[1], "build") == 0) {'''
assert old in src
src = src.replace(old, new)
open('planb64.cpp','w').write(src)
PYEOF
make -C /work/submit clean >/dev/null && make -C /work/submit >/dev/null && echo built
# quick re-verify the public check plus argc==1
/work/submit/planb64; echo "exit=$?"
rm -f /work/example.idx; /work/submit/planb64 build /work/examples/fib.txt /work/example.idx && cmp /work/example.idx /work/examples/expected.idx && echo "IDX MATCH"
